+func trieProof(t *testing.T, tree *trie.Trie, key []byte) []string {
+	t.Helper()
+	db := memorydb.New()
+	defer db.Close()
+	if err := tree.Prove(key, db); err != nil {
+		t.Fatal(err)
+	}
+	it := db.NewIterator(nil, nil)
