	"github.com/ethereum/go-ethereum/ethclient/gethclient"
	"github.com/ethereum/go-ethereum/log"
	"github.com/ethereum/go-ethereum/rpc"

	withdrawerbindings "github.com/base/withdrawer/bindings"
)

type FPWithdrawer struct {
	Ctx                 context.Context
	L1Client            *ethclient.Client
	L2Client            *rpc.Client
	L2TxHash            common.Hash
	Portal              *bindingspreview.OptimismPortal2
	Factory             *bindings.DisputeGameFactory
	AnchorStateRegistry *withdrawerbindings.AnchorStateRegistry
	Opts                *bind.TransactOpts
	GasMultiplier       float64      // Multiplier for estimated gas (default 1.0)
	UserGasLimit        uint64       // Original user-specified gas limit (0 means auto-estimate)
	DryRun              bool         // Simulate transactions without submitting
	Retry               *RetryConfig // Bind contracts with NewRetryingBackend using this config.
}

func (w *FPWithdrawer) CheckIfProvable() error {
	l2WithdrawalBlock, err := txBlock(w.Ctx, w.L2Client, w.L2TxHash, w.Retry)
	if err != nil {
		return fmt.Errorf("error querying withdrawal tx block: %w", err)
	}

	latestGame, err := withdrawals.FindLatestGame(w.Ctx, &w.Factory.DisputeGameFactoryCaller, &w.Portal.OptimismPortal2Caller)
	if err != nil {
		return fmt.Errorf("failed to find latest game: %w", err)
	}
	l2BlockNumber := new(big.Int).SetBytes(latestGame.ExtraData[0:32])

	if l2BlockNumber.Uint64() < l2WithdrawalBlock.Uint64() {
		return fmt.Errorf("the latest L2 block proposed in the DisputeGameFactory is %d and is not past L2 block %d that includes the withdrawal - the withdrawal cannot be proven yet",
			l2BlockNumber.Uint64(), l2WithdrawalBlock.Uint64())
	}
	return nil
}

func (w *FPWithdrawer) getWithdrawalHash() (common.Hash, error) {
	l2 := retryingL2{Client: ethclient.NewClient(w.L2Client), config: w.Retry}
	receipt, err := l2.TransactionReceipt(w.Ctx, w.L2TxHash)
	if err != nil {
		return common.HexToHash(""), err
	}

	ev, err := withdrawals.ParseMessagePassed(receipt)
	if err != nil {
		return common.HexToHash(""), err
	}

	hash, err := withdrawals.WithdrawalHash(ev)
	if err != nil {
		return common.HexToHash(""), err
	}

	return hash, nil
}

func (w *FPWithdrawer) GetProvenWithdrawalTime() (uint64, error) {
	hash, err := w.getWithdrawalHash()
	if err != nil {
		return 0, err
	}

	// the proven withdrawal structure now contains an additional mapping, as withdrawal proofs are now stored per submitter address
	provenWithdrawal, err := w.Portal.ProvenWithdrawals(&bind.CallOpts{Context: w.Ctx}, hash, w.Opts.From)
	if err != nil {
		return 0, err
	}
	if provenWithdrawal.Timestamp == 0 {
		// No proof exists yet, so there is no dispute game to validate.
		return 0, nil
	}

	invalidated, err := w.isDisputeGameInvalidated(provenWithdrawal.DisputeGameProxy)
	if err != nil || invalidated {
		return 0, err
	}

	return provenWithdrawal.Timestamp, nil
}

func (w *FPWithdrawer) isDisputeGameInvalidated(game common.Address) (bool, error) {
	callOpts := &bind.CallOpts{Context: w.Ctx}

	blacklisted, err := w.AnchorStateRegistry.IsGameBlacklisted(callOpts, game)
	if err != nil {
		return false, err
	}
	if blacklisted {
		return true, nil
	}

	return w.AnchorStateRegistry.IsGameRetired(callOpts, game)
}

func (w *FPWithdrawer) ProveWithdrawal() error {
	l2 := retryingL2{Client: ethclient.NewClient(w.L2Client), proof: gethclient.New(w.L2Client), config: w.Retry}

	params, err := withdrawals.ProveWithdrawalParametersFaultProofs(w.Ctx, l2, l2, l2, w.L2TxHash, &w.Factory.DisputeGameFactoryCaller, &w.Portal.OptimismPortal2Caller)
	if err != nil {
		return err
	}

	withdrawalTx := bindingspreview.TypesWithdrawalTransaction{
		Nonce:    params.Nonce,
		Sender:   params.Sender,
		Target:   params.Target,
		Value:    params.Value,
		GasLimit: params.GasLimit,
		Data:     params.Data,
	}
	outputRootProof := bindingspreview.TypesOutputRootProof{
		Version:                  params.OutputRootProof.Version,
		StateRoot:                params.OutputRootProof.StateRoot,
		MessagePasserStorageRoot: params.OutputRootProof.MessagePasserStorageRoot,
		LatestBlockhash:          params.OutputRootProof.LatestBlockhash,
	}

	// Prepare gas options with multiplier if configured
	simulatedTx, err := prepareGasOpts(w.Opts, w.UserGasLimit, w.GasMultiplier, w.DryRun, func(opts *bind.TransactOpts) (*types.Transaction, error) {
		return w.Portal.ProveWithdrawalTransaction(
			opts,
			withdrawalTx,
			params.L2OutputIndex,
			outputRootProof,
			params.WithdrawalProof,
		)
	})
	if err != nil {
		return err
	}

	if w.DryRun {
		printDryRun("ProveWithdrawal", simulatedTx, w.Opts.From, w.Opts.GasLimit)
		return nil
	}

	noSendOpts := *w.Opts
	noSendOpts.NoSend = true
	tx, err := w.Portal.ProveWithdrawalTransaction(
		&noSendOpts,
		withdrawalTx,
		params.L2OutputIndex, // this is overloaded and is the DisputeGame index in this context
		outputRootProof,
		params.WithdrawalProof,
	)
	if err != nil {
		return err
	}
	if w.Opts.NoSend {
		log.Info("Prepared withdrawal transaction without submission", "l1TxHash", tx.Hash())
		return nil
	}
	if err := sendTransaction(w.Ctx, w.Opts.Context, w.L1Client, w.Retry, "ProveWithdrawal.send", tx); err != nil {
		return err
	}

	log.Info("Proved withdrawal", "l2TxHash", w.L2TxHash, "l1TxHash", tx.Hash())

	return waitForConfirmation(w.Ctx, w.L1Client, tx.Hash(), "proof", w.Retry)
}

func (w *FPWithdrawer) IsProofFinalized() (bool, error) {
	hash, err := w.getWithdrawalHash()
	if err != nil {
		return false, err
	}
	return w.Portal.FinalizedWithdrawals(&bind.CallOpts{Context: w.Ctx}, hash)
}

func (w *FPWithdrawer) FinalizeWithdrawal() error {
	// get the withdrawal hash
	hash, err := w.getWithdrawalHash()
	if err != nil {
		return err
	}

	// check if the withdrawal can be finalized using the calculated withdrawal hash
	err = w.Portal.CheckWithdrawal(&bind.CallOpts{Context: w.Ctx}, hash, w.Opts.From)
	if err != nil {
		return err
	}

	// get the WithdrawalTransaction info needed to finalize the withdrawal
	l2 := retryingL2{Client: ethclient.NewClient(w.L2Client), config: w.Retry}

	// Transaction receipt
	receipt, err := l2.TransactionReceipt(w.Ctx, w.L2TxHash)
	if err != nil {
		return err
	}
	// Parse the receipt
	ev, err := withdrawals.ParseMessagePassed(receipt)
	if err != nil {
		return err
	}

	withdrawalTx := bindingspreview.TypesWithdrawalTransaction{
		Nonce:    ev.Nonce,
		Sender:   ev.Sender,
		Target:   ev.Target,
		Value:    ev.Value,
		GasLimit: ev.GasLimit,
		Data:     ev.Data,
	}

	// Prepare gas options with multiplier if configured
	simulatedTx, err := prepareGasOpts(w.Opts, w.UserGasLimit, w.GasMultiplier, w.DryRun, func(opts *bind.TransactOpts) (*types.Transaction, error) {
		return w.Portal.FinalizeWithdrawalTransaction(opts, withdrawalTx)
	})
	if err != nil {
		return err
	}

	if w.DryRun {
		printDryRun("FinalizeWithdrawal", simulatedTx, w.Opts.From, w.Opts.GasLimit)
		return nil
	}

	noSendOpts := *w.Opts
	noSendOpts.NoSend = true
	tx, err := w.Portal.FinalizeWithdrawalTransaction(&noSendOpts, withdrawalTx)
	if err != nil {
		return err
	}
	if w.Opts.NoSend {
		log.Info("Prepared withdrawal transaction without submission", "l1TxHash", tx.Hash())
		return nil
	}
	if err := sendTransaction(w.Ctx, w.Opts.Context, w.L1Client, w.Retry, "FinalizeWithdrawal.send", tx); err != nil {
		return err
	}

	log.Info("Completed withdrawal", "l2TxHash", w.L2TxHash, "l1TxHash", tx.Hash())

	return waitForConfirmation(w.Ctx, w.L1Client, tx.Hash(), "finalization", w.Retry)
}


